add_action( 'woocommerce_checkout_process', 'perfectpixel_validate_vat_with_vies' );

function perfectpixel_validate_vat_with_vies() {
	$field   = '{{vat_field}}';
	$number  = isset( $_POST[ $field ] ) ? strtoupper( preg_replace( '/[^A-Za-z0-9]/', '', wp_unslash( $_POST[ $field ] ) ) ) : ''; // phpcs:ignore WordPress.Security.NonceVerification
	$country = isset( $_POST['billing_country'] ) ? strtoupper( sanitize_text_field( wp_unslash( $_POST['billing_country'] ) ) ) : ''; // phpcs:ignore WordPress.Security.NonceVerification

	if ( '' === $number || '' === $country ) {
		return;
	}

	// VIES uses EL for Greece; strip the country prefix if the customer typed it.
	$vies_country = 'GR' === $country ? 'EL' : $country;
	if ( 0 === strpos( $number, $vies_country ) || 0 === strpos( $number, $country ) ) {
		$number = substr( $number, 2 );
	}

	$url      = sprintf( 'https://ec.europa.eu/taxation_customs/vies/rest-api/ms/%s/vat/%s', rawurlencode( $vies_country ), rawurlencode( $number ) );
	$response = wp_remote_get( $url, array( 'timeout' => 10 ) );

	if ( is_wp_error( $response ) || 200 !== (int) wp_remote_retrieve_response_code( $response ) ) {
		return; // Service unavailable: do not block the order.
	}

	$data = json_decode( wp_remote_retrieve_body( $response ), true );
	if ( ! is_array( $data ) ) {
		return;
	}

	$valid = isset( $data['isValid'] ) ? (bool) $data['isValid'] : ( 'VALID' === ( $data['userError'] ?? '' ) );
	if ( ! $valid ) {
		wc_add_notice( __( 'The VAT number is not valid according to the EU VIES service. Please check it and try again.', 'woocommerce' ), 'error' );
	}
}
